-- Generated by go run ./cmd/schema-baseline.
-- Development fresh-install baseline for unreleased schema version 105.
-- Read only with KIKOTO_MODE=development. Do not use this file to upgrade an existing database.

CREATE TABLE app_setting (
  key TEXT PRIMARY KEY,
  value_json TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE audit_log (
  id INTEGER PRIMARY KEY,
  actor_user_id INTEGER REFERENCES user_account(id) ON DELETE SET NULL,
  action TEXT NOT NULL,
  target_type TEXT NOT NULL DEFAULT '',
  target_id TEXT NOT NULL DEFAULT '',
  detail_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "availability_watch" (
  id INTEGER PRIMARY KEY CHECK(id = 1),
  configured_by_user_id INTEGER REFERENCES user_account(id) ON DELETE SET NULL,
  action TEXT NOT NULL DEFAULT 'monitor' CHECK(action IN ('monitor', 'track', 'fetch', 'track_fetch')),
  source_id INTEGER REFERENCES file_source(id) ON DELETE SET NULL,
  exclude_extensions_json TEXT NOT NULL DEFAULT '["wav"]',
  revision INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "availability_watch_target" (
  id INTEGER PRIMARY KEY,
  watch_id INTEGER NOT NULL REFERENCES "availability_watch"(id) ON DELETE CASCADE,
  work_code TEXT NOT NULL,
  active INTEGER NOT NULL DEFAULT 1,
  state TEXT NOT NULL DEFAULT 'monitoring' CHECK(state IN ('monitoring', 'ready', 'action_queued', 'completed', 'error', 'disabled')),
  next_check_at TEXT,
  last_checked_at TEXT,
  last_status TEXT NOT NULL DEFAULT '',
  last_error TEXT NOT NULL DEFAULT '',
  available_source_id INTEGER REFERENCES file_source(id) ON DELETE SET NULL,
  availability_epoch INTEGER NOT NULL DEFAULT 0,
  track_run_id INTEGER REFERENCES workflow_run(id) ON DELETE SET NULL,
  fetch_run_id INTEGER REFERENCES workflow_run(id) ON DELETE SET NULL,
  revision INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, available_code TEXT NOT NULL DEFAULT '', metadata_synced_at TEXT,
  UNIQUE(watch_id, work_code)
);

CREATE TABLE catalog_series (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    work_id INTEGER UNIQUE REFERENCES work(id) ON DELETE RESTRICT,
    source_id INTEGER REFERENCES file_source(id) ON DELETE SET NULL,
    source_key TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE catalog_series_member (
    series_id INTEGER NOT NULL REFERENCES catalog_series(id) ON DELETE RESTRICT,
    catalog_entry_id INTEGER NOT NULL UNIQUE REFERENCES source_catalog_entry(id) ON DELETE RESTRICT,
    position INTEGER NOT NULL CHECK(position > 0),
    evidence TEXT NOT NULL CHECK(evidence IN ('directory','manual')),
    PRIMARY KEY(series_id,position)
);

CREATE TABLE catalog_series_preview (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    actor_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
    payload_json TEXT NOT NULL,
    fingerprint TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','completed')),
    series_id INTEGER REFERENCES catalog_series(id) ON DELETE RESTRICT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE content_translation (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  cache_key TEXT NOT NULL UNIQUE,
  entity_kind TEXT NOT NULL CHECK(entity_kind IN ('entry','series','work')),
  entity_id INTEGER NOT NULL,
  entity_key TEXT NOT NULL DEFAULT '',
  field TEXT NOT NULL CHECK(field IN ('title','description','tag','directory')),
  language TEXT NOT NULL,
  source_text TEXT NOT NULL DEFAULT '',
  translated_text TEXT NOT NULL,
  origin TEXT NOT NULL CHECK(origin IN ('native','model')),
  model TEXT NOT NULL DEFAULT '',
  template_version TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, config_key TEXT NOT NULL DEFAULT '', source_id INTEGER, browsable INTEGER NOT NULL DEFAULT 0);

CREATE VIRTUAL TABLE content_translation_search USING fts5(
  translated_text,
  content='content_translation',
  content_rowid='id',
  tokenize='trigram'
);

CREATE TABLE dlsite_genre_name (
  genre_id INTEGER NOT NULL CHECK(genre_id > 0),
  language TEXT NOT NULL,
  name TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (genre_id, language)
);

CREATE TABLE dlsite_genre_name_gap (
  genre_id INTEGER NOT NULL CHECK(genre_id > 0),
  language TEXT NOT NULL CHECK(language IN ('zh-cn', 'zh-tw', 'en-us', 'ko-kr')),
  attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts >= 0),
  exhausted INTEGER NOT NULL DEFAULT 0 CHECK(exhausted IN (0, 1)),
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(genre_id, language)
) WITHOUT ROWID;

CREATE TABLE dlsite_genre_name_request (
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  language TEXT NOT NULL CHECK(language IN ('zh-cn', 'zh-tw', 'en-us', 'ko-kr')),
  outcome TEXT NOT NULL CHECK(outcome IN ('learned', 'no_names', 'not_found')),
  requested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(work_id, language)
) WITHOUT ROWID;

CREATE TABLE dlsite_metadata_variant (
  id INTEGER PRIMARY KEY,
  logical_work_id INTEGER NOT NULL REFERENCES logical_work(id) ON DELETE CASCADE,
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  provider_id INTEGER NOT NULL REFERENCES metadata_provider(id) ON DELETE CASCADE,
  external_id TEXT NOT NULL,
  edition_language TEXT NOT NULL DEFAULT '',
  request_locale TEXT NOT NULL DEFAULT '',
  title TEXT NOT NULL DEFAULT '',
  tags_json TEXT NOT NULL DEFAULT '[]',
  content_hash TEXT NOT NULL DEFAULT '',
  fetched_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  -- One DLsite work code is one language edition.  The provider declaration
  -- and request locale may be corrected by a later fetch without creating a
  -- second display variant for the same edition.
  UNIQUE(provider_id, work_id)
);

CREATE TABLE favorite_list (
  id INTEGER PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, kind TEXT NOT NULL DEFAULT 'user' CHECK(kind IN ('marked', 'user')), icon TEXT NOT NULL DEFAULT '',
  UNIQUE(user_id, name)
);

CREATE TABLE favorite_list_item (
  id INTEGER PRIMARY KEY,
  list_id INTEGER NOT NULL REFERENCES favorite_list(id) ON DELETE CASCADE,
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  note TEXT NOT NULL DEFAULT '',
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(list_id, work_id)
);

CREATE TABLE file_source (
  id INTEGER PRIMARY KEY,
  code TEXT NOT NULL UNIQUE,
  display_name TEXT NOT NULL,
  source_type TEXT NOT NULL,
  priority INTEGER NOT NULL DEFAULT 100,
  enabled INTEGER NOT NULL DEFAULT 1,
  config_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE file_source_endpoint (
  id INTEGER PRIMARY KEY,
  file_source_id INTEGER NOT NULL REFERENCES file_source(id) ON DELETE CASCADE,
  base_url TEXT NOT NULL DEFAULT '',
  api_url TEXT NOT NULL DEFAULT '',
  fallback_url TEXT NOT NULL DEFAULT '',
  auth_type TEXT NOT NULL DEFAULT 'none',
  credential_ref TEXT NOT NULL DEFAULT '',
  health_status TEXT NOT NULL DEFAULT 'unknown',
  last_checked_at TEXT
, work_url_template TEXT NOT NULL DEFAULT '/work/{code}', restrict_outbound_hosts INTEGER NOT NULL DEFAULT 0 CHECK(restrict_outbound_hosts IN (0, 1)), allowed_host_patterns_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(allowed_host_patterns_json)));

CREATE TABLE filesystem_trigger_state (
  trigger_id INTEGER PRIMARY KEY REFERENCES workflow_trigger(id) ON DELETE CASCADE,
  watched_directory_count INTEGER NOT NULL DEFAULT 0,
  last_event_at TEXT,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE legacy_workflow_snapshot (
  original_id INTEGER PRIMARY KEY,
  code TEXT NOT NULL,
  display_name TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  definition_json TEXT NOT NULL,
  owner_user_id INTEGER,
  created_by_user_id INTEGER,
  triggers_json TEXT NOT NULL DEFAULT '[]',
  review_status TEXT NOT NULL DEFAULT 'pending' CHECK(review_status IN ('pending', 'converted', 'skipped')),
  converted_preset_code TEXT NOT NULL DEFAULT '',
  captured_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE legacy_workflow_trigger_migration (
  original_trigger_id INTEGER PRIMARY KEY,
  original_definition_id INTEGER NOT NULL REFERENCES legacy_workflow_snapshot(original_id) ON DELETE CASCADE,
  new_trigger_id INTEGER NOT NULL REFERENCES workflow_trigger(id) ON DELETE CASCADE
);

CREATE TABLE library_layout_migration (
  id INTEGER PRIMARY KEY CHECK(id = 1),
  status TEXT NOT NULL CHECK(status IN ('running', 'failed', 'completed')),
  phase TEXT NOT NULL,
  requested_json TEXT NOT NULL,
  plan_json TEXT NOT NULL,
  progress_current INTEGER NOT NULL DEFAULT 0,
  progress_total INTEGER NOT NULL DEFAULT 0,
  progress_bytes_current INTEGER NOT NULL DEFAULT 0,
  progress_bytes_total INTEGER NOT NULL DEFAULT 0,
  scan_run_id INTEGER REFERENCES workflow_run(id) ON DELETE SET NULL,
  error_message TEXT NOT NULL DEFAULT '',
  started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "logical_work" (
  id INTEGER PRIMARY KEY,
  canonical_work_id INTEGER REFERENCES work(id) ON DELETE SET NULL,
  canonical_code TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE media_file_location (
  id INTEGER PRIMARY KEY,
  media_item_id INTEGER NOT NULL REFERENCES media_item(id) ON DELETE CASCADE,
  file_source_id INTEGER NOT NULL REFERENCES file_source(id) ON DELETE CASCADE,
  location_type TEXT NOT NULL,
  path TEXT NOT NULL DEFAULT '',
  stream_url TEXT NOT NULL DEFAULT '',
  download_url TEXT NOT NULL DEFAULT '',
  remote_hash TEXT NOT NULL DEFAULT '',
  size_bytes INTEGER,
  duration_seconds INTEGER,
  availability TEXT NOT NULL DEFAULT 'unknown',
  last_checked_at TEXT
, file_version TEXT NOT NULL DEFAULT '');

CREATE TABLE media_item (
  id INTEGER PRIMARY KEY,
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  parent_id INTEGER REFERENCES media_item(id) ON DELETE CASCADE,
  kind TEXT NOT NULL,
  title TEXT NOT NULL,
  disc_no INTEGER,
  track_no INTEGER,
  duration_seconds INTEGER,
  size_bytes INTEGER,
  fingerprint TEXT NOT NULL DEFAULT ''
, has_audio INTEGER, file_version TEXT NOT NULL DEFAULT '');

CREATE TABLE media_lyrics_assignment (
  audio_media_item_id INTEGER PRIMARY KEY REFERENCES media_item(id) ON DELETE CASCADE,
  lyrics_media_item_id INTEGER NOT NULL REFERENCES media_item(id) ON DELETE CASCADE,
  origin TEXT NOT NULL DEFAULT 'manual' CHECK(origin IN ('manual', 'remote_fetch')),
  assigned_by_user_id INTEGER REFERENCES user_account(id) ON DELETE SET NULL,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK(audio_media_item_id <> lyrics_media_item_id)
);

CREATE TABLE metadata_provider (
  id INTEGER PRIMARY KEY,
  code TEXT NOT NULL UNIQUE,
  display_name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE metadata_snapshot (
  id INTEGER PRIMARY KEY,
  work_id INTEGER REFERENCES work(id) ON DELETE SET NULL,
  provider_id INTEGER NOT NULL REFERENCES metadata_provider(id),
  external_id TEXT NOT NULL,
  snapshot_json TEXT NOT NULL,
  fetched_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, variant_key TEXT NOT NULL DEFAULT '', edition_language TEXT NOT NULL DEFAULT '', request_locale TEXT NOT NULL DEFAULT '', content_hash TEXT NOT NULL DEFAULT '');

CREATE TABLE metadata_snapshot_card_summary (
  snapshot_id INTEGER PRIMARY KEY REFERENCES metadata_snapshot(id) ON DELETE CASCADE,
  version INTEGER NOT NULL,
  summary_json TEXT NOT NULL
);

CREATE TABLE metadata_snapshot_card_summary_dirty (
  snapshot_id INTEGER PRIMARY KEY REFERENCES metadata_snapshot(id) ON DELETE CASCADE
);

CREATE TABLE metadata_sync_attempt (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE metadata_sync_attempt_run (
  attempt_id INTEGER NOT NULL REFERENCES metadata_sync_attempt(id) ON DELETE CASCADE,
  workflow_run_id INTEGER NOT NULL REFERENCES workflow_run(id) ON DELETE CASCADE,
  PRIMARY KEY(attempt_id, workflow_run_id)
);

CREATE TABLE metadata_sync_attempt_work (
  attempt_id INTEGER NOT NULL REFERENCES metadata_sync_attempt(id) ON DELETE CASCADE,
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  provider_id INTEGER NOT NULL REFERENCES metadata_provider(id) ON DELETE CASCADE,
  component TEXT NOT NULL CHECK(component IN ('metadata', 'cover')),
  status TEXT NOT NULL CHECK(status IN ('succeeded', 'failed', 'unavailable')),
  PRIMARY KEY(attempt_id, work_id, provider_id, component)
);

CREATE TABLE metadata_tag (
  tag_id INTEGER PRIMARY KEY REFERENCES tag(id) ON DELETE RESTRICT,
  dlsite_genre_id INTEGER UNIQUE CHECK(dlsite_genre_id > 0),
  merged_into_tag_id INTEGER REFERENCES metadata_tag(tag_id) ON DELETE RESTRICT,
  hidden INTEGER NOT NULL DEFAULT 0 CHECK(hidden IN (0, 1)),
  created_by_user_id INTEGER REFERENCES user_account(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK(merged_into_tag_id IS NULL OR merged_into_tag_id <> tag_id)
);

CREATE TABLE metadata_tag_name (
  tag_id INTEGER NOT NULL REFERENCES metadata_tag(tag_id) ON DELETE CASCADE,
  language TEXT NOT NULL DEFAULT '',
  name TEXT NOT NULL CHECK(TRIM(name) <> ''),
  updated_by_user_id INTEGER REFERENCES user_account(id) ON DELETE SET NULL,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(tag_id, language)
);

CREATE TABLE metadata_tag_provider_name (
  tag_id INTEGER NOT NULL REFERENCES metadata_tag(tag_id) ON DELETE CASCADE,
  language TEXT NOT NULL CHECK(language IN ('', 'ja-jp', 'zh-cn', 'zh-tw', 'en-us', 'ko-kr')),
  name TEXT NOT NULL CHECK(TRIM(name) <> '' AND LENGTH(CAST(name AS BLOB)) <= 512),
  provider_id INTEGER NOT NULL REFERENCES metadata_provider(id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(tag_id, language)
) WITHOUT ROWID;

CREATE TABLE party (
  id INTEGER PRIMARY KEY,
  party_type TEXT NOT NULL DEFAULT 'circle',
  display_name TEXT NOT NULL,
  sort_name TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, manual_name TEXT NOT NULL DEFAULT '', provider_name TEXT NOT NULL DEFAULT '');

CREATE TABLE party_alias (
 id INTEGER PRIMARY KEY,
 party_id INTEGER NOT NULL REFERENCES party(id) ON DELETE CASCADE,
 alias TEXT NOT NULL CHECK(TRIM(alias)<>''),
 source TEXT NOT NULL DEFAULT 'manual',
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE(party_id,alias)
);

CREATE TABLE party_catalog_item (
  id INTEGER PRIMARY KEY,
  party_id INTEGER NOT NULL REFERENCES party(id) ON DELETE CASCADE,
  provider_id INTEGER NOT NULL REFERENCES metadata_provider(id),
  primary_code TEXT NOT NULL,
  title TEXT NOT NULL DEFAULT '',
  release_date TEXT,
  url TEXT NOT NULL DEFAULT '',
  catalog_status TEXT NOT NULL DEFAULT 'imported',
  dlsite_available INTEGER NOT NULL DEFAULT 1,
  raw_json TEXT NOT NULL DEFAULT '{}',
  last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(party_id, provider_id, primary_code)
);

CREATE TABLE party_catalog_refresh_state (
  party_id INTEGER NOT NULL REFERENCES party(id) ON DELETE CASCADE,
  provider_code TEXT NOT NULL,
  last_success_at TEXT,
  last_attempt_at TEXT,
  last_mode TEXT NOT NULL DEFAULT '',
  last_status TEXT NOT NULL DEFAULT '',
  last_run_id INTEGER,
  last_error TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(party_id, provider_code)
);

CREATE TABLE party_external_id (
  id INTEGER PRIMARY KEY,
  party_id INTEGER NOT NULL REFERENCES party(id) ON DELETE CASCADE,
  provider_id INTEGER NOT NULL REFERENCES metadata_provider(id),
  id_type TEXT NOT NULL,
  external_id TEXT NOT NULL,
  url TEXT NOT NULL DEFAULT '',
  is_primary INTEGER NOT NULL DEFAULT 0,
  UNIQUE(provider_id, id_type, external_id)
);

CREATE TABLE party_merge_review (
 id INTEGER PRIMARY KEY,
 target_party_id INTEGER NOT NULL REFERENCES party(id) ON DELETE CASCADE,
 source_party_id INTEGER NOT NULL,
 target_name TEXT NOT NULL,
 source_name TEXT NOT NULL,
 snapshot_json TEXT NOT NULL,
 status TEXT NOT NULL DEFAULT 'merged' CHECK(status IN ('merged','undone')),
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 undone_at TEXT
);

CREATE TABLE party_metadata_snapshot (
  id INTEGER PRIMARY KEY,
  party_id INTEGER REFERENCES party(id) ON DELETE SET NULL,
  provider_id INTEGER NOT NULL REFERENCES metadata_provider(id),
  external_id TEXT NOT NULL,
  snapshot_json TEXT NOT NULL,
  fetched_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE party_series (
  id INTEGER PRIMARY KEY,
  party_id INTEGER NOT NULL REFERENCES party(id) ON DELETE CASCADE,
  provider_id INTEGER NOT NULL REFERENCES metadata_provider(id),
  title_id TEXT NOT NULL,
  name TEXT NOT NULL,
  url TEXT NOT NULL DEFAULT '',
  declared_works INTEGER NOT NULL DEFAULT 0,
  raw_json TEXT NOT NULL DEFAULT '{}',
  last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(party_id, provider_id, title_id)
);

CREATE TABLE party_series_work (
  series_id INTEGER NOT NULL REFERENCES party_series(id) ON DELETE CASCADE,
  primary_code TEXT NOT NULL,
  position INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(series_id, primary_code)
);

CREATE TABLE person (
  id INTEGER PRIMARY KEY,
  display_name TEXT NOT NULL,
  sort_name TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(display_name)
);

CREATE TABLE person_alias (
  id INTEGER PRIMARY KEY,
  person_id INTEGER NOT NULL REFERENCES person(id) ON DELETE CASCADE,
  alias TEXT NOT NULL,
  source TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(person_id, alias)
);

CREATE TABLE person_external_id (
  id INTEGER PRIMARY KEY,
  person_id INTEGER NOT NULL REFERENCES person(id) ON DELETE CASCADE,
  provider_id INTEGER NOT NULL REFERENCES metadata_provider(id),
  id_type TEXT NOT NULL,
  external_id TEXT NOT NULL,
  url TEXT NOT NULL DEFAULT '',
  is_primary INTEGER NOT NULL DEFAULT 0,
  UNIQUE(provider_id, id_type, external_id)
);

CREATE TABLE person_merge_review (
  id INTEGER PRIMARY KEY,
  target_person_id INTEGER NOT NULL REFERENCES person(id) ON DELETE CASCADE,
  source_person_id INTEGER NOT NULL,
  target_name TEXT NOT NULL,
  source_name TEXT NOT NULL,
  snapshot_json TEXT NOT NULL DEFAULT '{}',
  status TEXT NOT NULL DEFAULT 'merged',
  undone_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE personal_transfer_progress (
 user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
 work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
 progress_json TEXT NOT NULL CHECK(json_valid(progress_json)),
 PRIMARY KEY(user_id,work_id)
);

CREATE TABLE personal_transfer_ref (
 ref TEXT PRIMARY KEY,
 work_id INTEGER REFERENCES work(id) ON DELETE CASCADE,
 catalog_entry_id INTEGER REFERENCES source_catalog_entry(id) ON DELETE CASCADE,
 series_id INTEGER REFERENCES catalog_series(id) ON DELETE CASCADE,
 is_primary INTEGER NOT NULL DEFAULT 0 CHECK(is_primary IN (0,1)),
 object_kind TEXT NOT NULL DEFAULT 'work' CHECK(object_kind IN ('work','episode','series')),
 CHECK((work_id IS NOT NULL)+(catalog_entry_id IS NOT NULL)+(series_id IS NOT NULL)=1),
 CHECK(is_primary=0 OR work_id IS NOT NULL)
);

CREATE TABLE recommendation_catalog_dirty (
  work_id INTEGER PRIMARY KEY,
  retry_count INTEGER NOT NULL DEFAULT 0,
  retry_after INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE recommendation_catalog_entity (
  kind TEXT NOT NULL,
  entity_id INTEGER NOT NULL,
  work_id INTEGER NOT NULL,
  explore_key INTEGER NOT NULL,
  valid_from INTEGER NOT NULL,
  valid_to INTEGER,
  PRIMARY KEY(kind, entity_id, work_id, valid_from)
);

CREATE TABLE recommendation_catalog_epoch (
  id INTEGER PRIMARY KEY,
  work_count INTEGER NOT NULL DEFAULT 0 CHECK(work_count >= 0),
  published INTEGER NOT NULL DEFAULT 0 CHECK(published IN (0, 1)),
  changed INTEGER NOT NULL DEFAULT 0 CHECK(changed IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE recommendation_catalog_frequency (
  kind TEXT NOT NULL,
  entity_id INTEGER NOT NULL,
  valid_from INTEGER NOT NULL,
  valid_to INTEGER,
  work_count INTEGER NOT NULL CHECK(work_count >= 0),
  PRIMARY KEY(kind, entity_id, valid_from)
);

CREATE TABLE recommendation_catalog_name (
  kind TEXT NOT NULL,
  source_id INTEGER NOT NULL,
  name TEXT NOT NULL,
  entity_id INTEGER NOT NULL,
  valid_from INTEGER NOT NULL,
  valid_to INTEGER,
  PRIMARY KEY(kind, source_id, name, valid_from)
);

CREATE TABLE recommendation_catalog_state (
  id INTEGER PRIMARY KEY CHECK(id = 1),
  published_epoch INTEGER REFERENCES recommendation_catalog_epoch(id),
  building_epoch INTEGER REFERENCES recommendation_catalog_epoch(id)
);

CREATE TABLE recommendation_catalog_work (
  work_id INTEGER NOT NULL,
  primary_code TEXT NOT NULL,
  valid_from INTEGER NOT NULL,
  valid_to INTEGER,
  features_json TEXT NOT NULL CHECK(json_valid(features_json)),
  PRIMARY KEY(work_id, valid_from)
);

CREATE TABLE recommendation_client_session (
  user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
  session_id TEXT NOT NULL CHECK(length(session_id) BETWEEN 1 AND 64),
  generation_id INTEGER REFERENCES recommendation_generation(id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(user_id, session_id)
);

CREATE TABLE recommendation_event (
  id INTEGER PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
  work_id INTEGER REFERENCES work(id) ON DELETE CASCADE,
  event_type TEXT NOT NULL CHECK(event_type IN ('impression', 'open', 'play', 'positive_mark', 'paused_mark', 'reshuffle')),
  context_id TEXT NOT NULL DEFAULT '',
  algorithm_version TEXT NOT NULL DEFAULT '',
  seed INTEGER NOT NULL DEFAULT 0,
  rank INTEGER NOT NULL DEFAULT 0,
  score INTEGER NOT NULL DEFAULT 0 CHECK(score BETWEEN 0 AND 100),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE recommendation_generation (
  id INTEGER PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
  algorithm_version TEXT NOT NULL,
  config_json TEXT NOT NULL,
  input_revision INTEGER NOT NULL CHECK(input_revision >= 0),
  user_revision INTEGER NOT NULL CHECK(user_revision >= 0),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, catalog_epoch INTEGER REFERENCES recommendation_catalog_epoch(id), ready INTEGER NOT NULL DEFAULT 0 CHECK(ready IN (0, 1)));

CREATE TABLE recommendation_generation_profile (
  generation_id INTEGER PRIMARY KEY REFERENCES recommendation_generation(id) ON DELETE CASCADE,
  profile_json TEXT NOT NULL CHECK(json_valid(profile_json))
);

CREATE TABLE recommendation_generation_state (
  generation_id INTEGER NOT NULL REFERENCES recommendation_generation(id) ON DELETE CASCADE,
  work_id INTEGER NOT NULL,
  primary_code TEXT NOT NULL,
  listening_status TEXT NOT NULL,
  favorite INTEGER NOT NULL CHECK(favorite IN (0, 1)),
  PRIMARY KEY(generation_id, work_id)
);

CREATE TABLE recommendation_input_revision (
  id INTEGER PRIMARY KEY CHECK(id = 1),
  revision INTEGER NOT NULL DEFAULT 0 CHECK(revision >= 0),
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE recommendation_name_dirty (
  kind TEXT NOT NULL,
  entity_id INTEGER NOT NULL,
  retry_count INTEGER NOT NULL DEFAULT 0,
  retry_after INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY(kind, entity_id)
);

CREATE TABLE recommendation_query_candidate (
  context_id TEXT NOT NULL REFERENCES recommendation_query_context(id) ON DELETE CASCADE,
  work_id INTEGER NOT NULL,
  primary_code TEXT NOT NULL,
  rank INTEGER NOT NULL CHECK(rank BETWEEN 1 AND 500),
  signals_json TEXT NOT NULL CHECK(json_valid(signals_json)),
  PRIMARY KEY(context_id, work_id),
  UNIQUE(context_id, rank)
);

CREATE TABLE recommendation_query_checkpoint (
  context_id TEXT NOT NULL REFERENCES recommendation_query_context(id) ON DELETE CASCADE,
  lane TEXT NOT NULL,
  exact_rank INTEGER NOT NULL,
  tail_rank INTEGER NOT NULL,
  explore_key INTEGER NOT NULL,
  work_id INTEGER NOT NULL,
  membership_revision TEXT NOT NULL,
  PRIMARY KEY(context_id, lane, exact_rank, tail_rank)
);

CREATE TABLE recommendation_query_context (
  id TEXT PRIMARY KEY CHECK(length(id) = 64),
  generation_id INTEGER NOT NULL REFERENCES recommendation_generation(id) ON DELETE CASCADE,
  seed INTEGER NOT NULL,
  direction TEXT NOT NULL,
  candidate_count INTEGER NOT NULL CHECK(candidate_count BETWEEN 0 AND 2000),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE recommendation_snapshot (
  generation_id INTEGER NOT NULL REFERENCES recommendation_generation(id) ON DELETE CASCADE,
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  listening_status TEXT NOT NULL DEFAULT 'none'
    CHECK(listening_status IN ('none', 'want_to_listen', 'listening', 'finished', 'relisten', 'paused')),
  favorite INTEGER NOT NULL DEFAULT 0 CHECK(favorite IN (0, 1)),
  positive_tag_matches INTEGER NOT NULL DEFAULT 0 CHECK(positive_tag_matches >= 0),
  positive_voice_matches INTEGER NOT NULL DEFAULT 0 CHECK(positive_voice_matches >= 0),
  positive_circle_matches INTEGER NOT NULL DEFAULT 0 CHECK(positive_circle_matches >= 0),
  negative_tag_matches INTEGER NOT NULL DEFAULT 0 CHECK(negative_tag_matches >= 0),
  negative_voice_matches INTEGER NOT NULL DEFAULT 0 CHECK(negative_voice_matches >= 0),
  negative_circle_matches INTEGER NOT NULL DEFAULT 0 CHECK(negative_circle_matches >= 0),
  score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 100), affinity_json TEXT NOT NULL DEFAULT '{}'
  CHECK(json_valid(affinity_json)), diversity_penalty INTEGER NOT NULL DEFAULT 0
  CHECK(diversity_penalty BETWEEN 0 AND 8),
  PRIMARY KEY(generation_id, work_id)
);

CREATE TABLE recommendation_snapshot_state (
  user_id INTEGER PRIMARY KEY REFERENCES user_account(id) ON DELETE CASCADE,
  current_generation_id INTEGER REFERENCES recommendation_generation(id) ON DELETE SET NULL,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE recommendation_user_revision (
  user_id INTEGER PRIMARY KEY REFERENCES user_account(id) ON DELETE CASCADE,
  revision INTEGER NOT NULL DEFAULT 0 CHECK(revision >= 0),
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE remote_fetch_manifest (
  id INTEGER PRIMARY KEY,
  workflow_run_id INTEGER NOT NULL REFERENCES workflow_run(id) ON DELETE CASCADE,
  workflow_job_id INTEGER REFERENCES workflow_job(id) ON DELETE SET NULL,
  request_id TEXT NOT NULL DEFAULT '',
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  remote_source_id INTEGER NOT NULL REFERENCES file_source(id) ON DELETE CASCADE,
  local_source_id INTEGER NOT NULL REFERENCES file_source(id) ON DELETE CASCADE,
  edition_code TEXT NOT NULL,
  target_root TEXT NOT NULL,
  staging_root TEXT NOT NULL,
  backup_root TEXT NOT NULL DEFAULT '',
  state TEXT NOT NULL DEFAULT 'planned',
  plan_json TEXT NOT NULL DEFAULT '{}',
  error_message TEXT NOT NULL DEFAULT '',
  published_at TEXT,
  registered_at TEXT,
  completed_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, staging_cleaned_at TEXT,
  UNIQUE(workflow_run_id)
);

CREATE TABLE remote_fetch_manifest_item (
  id INTEGER PRIMARY KEY,
  manifest_id INTEGER NOT NULL REFERENCES remote_fetch_manifest(id) ON DELETE CASCADE,
  relative_path TEXT NOT NULL,
  target_path TEXT NOT NULL,
  source_kind TEXT NOT NULL,
  action TEXT NOT NULL,
  expected_size_bytes INTEGER,
  content_hash TEXT NOT NULL DEFAULT '',
  state TEXT NOT NULL DEFAULT 'planned',
  error_message TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  remote_source_id INTEGER REFERENCES file_source(id) ON DELETE SET NULL,
  source_path TEXT NOT NULL DEFAULT '',
  original_target_path TEXT NOT NULL DEFAULT '',
  resolution TEXT NOT NULL DEFAULT 'auto',
  UNIQUE(manifest_id, target_path)
);

CREATE TABLE remote_fetch_request (
  request_id TEXT PRIMARY KEY,
  source_id INTEGER NOT NULL REFERENCES file_source(id) ON DELETE CASCADE,
  work_code TEXT NOT NULL,
  workflow_run_id INTEGER NOT NULL REFERENCES workflow_run(id) ON DELETE CASCADE,
  result_json TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE remote_metadata_title_variant (
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  language TEXT NOT NULL CHECK(language IN ('origin','ja-jp','zh-cn','zh-tw','en-us','ko-kr')),
  provider_id INTEGER NOT NULL REFERENCES metadata_provider(id) ON DELETE CASCADE,
  edition_code TEXT NOT NULL,
  edition_language TEXT NOT NULL DEFAULT '',
  title TEXT NOT NULL,
  is_original INTEGER NOT NULL CHECK(is_original IN (0,1)),
  PRIMARY KEY(work_id,language)
) WITHOUT ROWID;

CREATE TABLE shared_association (
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 actor_id INTEGER REFERENCES user_account(id) ON DELETE SET NULL,
 operation TEXT NOT NULL DEFAULT 'link' CHECK(operation IN ('link','split')),
 split_of INTEGER REFERENCES shared_association(id) ON DELETE RESTRICT,
 status TEXT NOT NULL DEFAULT 'preview' CHECK(status IN ('preview','pending','completed','stale','undone')),
 version TEXT NOT NULL,
 fingerprint TEXT NOT NULL,
 snapshot_json TEXT NOT NULL,
 result_json TEXT NOT NULL DEFAULT '{}',
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE shared_association_decision (
 operation_id INTEGER NOT NULL REFERENCES shared_association(id) ON DELETE CASCADE,
 user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
 rating INTEGER CHECK(rating IS NULL OR rating BETWEEN 0 AND 5),
 note TEXT NOT NULL DEFAULT '',
 allocation TEXT NOT NULL DEFAULT '' CHECK(allocation IN ('','left','right','both')),
 PRIMARY KEY(operation_id,user_id)
);

CREATE TABLE shared_identity_member (
 work_id INTEGER PRIMARY KEY REFERENCES work(id) ON DELETE RESTRICT,
 identity_work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE RESTRICT,
 operation_id INTEGER NOT NULL REFERENCES shared_association(id) ON DELETE RESTRICT
);

CREATE TABLE shared_identity_revision (
 kind TEXT NOT NULL,
 entity_id INTEGER NOT NULL,
 revision INTEGER NOT NULL DEFAULT 1,
 PRIMARY KEY(kind,entity_id)
);

CREATE TABLE shared_review_revision (
 user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
 work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
 revision INTEGER NOT NULL DEFAULT 1,
 PRIMARY KEY(user_id,work_id)
);

CREATE TABLE source_catalog_audio_root (
    file_source_id INTEGER NOT NULL REFERENCES file_source(id) ON DELETE CASCADE,
    generation INTEGER NOT NULL,
    catalog_root TEXT NOT NULL,
    PRIMARY KEY(file_source_id,generation,catalog_root)
);

CREATE TABLE source_catalog_directory (
    file_source_id INTEGER NOT NULL REFERENCES file_source(id) ON DELETE CASCADE,
    path TEXT NOT NULL,
    generation INTEGER NOT NULL,
    revision INTEGER NOT NULL DEFAULT 1,
    partition_path TEXT NOT NULL,
    catalog_root TEXT NOT NULL DEFAULT '',
    children_cursor TEXT NOT NULL DEFAULT '',
    next_page INTEGER NOT NULL DEFAULT 1,
    expected_total INTEGER NOT NULL DEFAULT -1,
    status TEXT NOT NULL DEFAULT 'pending',
    attempts INTEGER NOT NULL DEFAULT 0,
    error_code TEXT NOT NULL DEFAULT '',
    completed_at TEXT, work_split TEXT NOT NULL DEFAULT '', observed_version TEXT NOT NULL DEFAULT '', listing_digest TEXT NOT NULL DEFAULT '', last_verified_run INTEGER NOT NULL DEFAULT 0, last_verified_at TEXT, sync_state TEXT NOT NULL DEFAULT '',
    PRIMARY KEY(file_source_id,path)
);

CREATE TABLE source_catalog_encoding_issue (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  file_source_id INTEGER NOT NULL REFERENCES file_source(id) ON DELETE CASCADE,
  parent_path TEXT NOT NULL,
  raw_name TEXT NOT NULL,          -- 原始名字，含 U+FFFD 或非法字节，不做任何清理
  candidate_code TEXT NOT NULL DEFAULT '',
  suggested_name TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'unresolved' CHECK(status IN ('unresolved','recovered','ignored')),
  resolved_path TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(file_source_id, parent_path, raw_name)
);

CREATE TABLE "source_catalog_entry" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  file_source_id INTEGER REFERENCES file_source(id) ON DELETE SET NULL,
  root_path TEXT NOT NULL,
  primary_code TEXT NOT NULL DEFAULT '',
  title TEXT NOT NULL,
  work_id INTEGER REFERENCES work(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  availability_status TEXT NOT NULL DEFAULT 'available'
    CHECK(availability_status IN ('available','unavailable','maintenance','restricted','unconfirmed_empty','missing','excluded')),
  status_checked_at TEXT,
  last_seen_generation INTEGER NOT NULL DEFAULT 0,
  discovered_generation INTEGER NOT NULL DEFAULT 0,
  content_fingerprint TEXT NOT NULL DEFAULT '',
  layout_fingerprint TEXT NOT NULL DEFAULT '',
  relocated_to_id INTEGER REFERENCES source_catalog_entry(id) ON DELETE RESTRICT,
  source_root TEXT NOT NULL DEFAULT '',
  sidecar_json TEXT NOT NULL DEFAULT '',
  sidecar_pending INTEGER NOT NULL DEFAULT 0 CHECK(sidecar_pending IN (0,1)),
  sidecar_attempts INTEGER NOT NULL DEFAULT 0,
  sidecar_revision TEXT NOT NULL DEFAULT '',
  sidecar_transient_attempts INTEGER NOT NULL DEFAULT 0,
  sidecar_retry_at TEXT NOT NULL DEFAULT '',
  sidecar_failure TEXT NOT NULL DEFAULT '',
  UNIQUE(file_source_id, root_path)
);

CREATE TABLE source_catalog_entry_admission (
  catalog_entry_id INTEGER PRIMARY KEY REFERENCES source_catalog_entry(id) ON DELETE CASCADE,
  generation INTEGER NOT NULL,
  files INTEGER NOT NULL CHECK(files >= 0),
  audio INTEGER NOT NULL CHECK(audio >= 0),
  non_audio INTEGER NOT NULL CHECK(non_audio >= 0),
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE source_catalog_episode_pending (
    source_id INTEGER NOT NULL REFERENCES file_source(id) ON DELETE CASCADE,
    parent_root TEXT NOT NULL,
    catalog_entry_root TEXT NOT NULL,
    catalog_entry_id INTEGER NOT NULL REFERENCES source_catalog_entry(id) ON DELETE CASCADE,
    PRIMARY KEY(source_id, parent_root, catalog_entry_id)
);

CREATE TABLE source_catalog_episode_publication (
    source_id INTEGER NOT NULL REFERENCES file_source(id) ON DELETE CASCADE,
    parent_root TEXT NOT NULL,
    state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending', 'published')),
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY(source_id, parent_root)
);

CREATE TABLE source_catalog_exclusion (
  id INTEGER PRIMARY KEY,
  file_source_id INTEGER NOT NULL REFERENCES file_source(id) ON DELETE CASCADE,
  path TEXT NOT NULL,
  mode TEXT NOT NULL DEFAULT 'whole',
  action TEXT NOT NULL DEFAULT 'exclude',
  note TEXT NOT NULL DEFAULT '',
  enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(file_source_id,path)
);

CREATE TABLE source_catalog_file (
  catalog_entry_id INTEGER NOT NULL REFERENCES source_catalog_entry(id) ON DELETE CASCADE,
  relative_path TEXT NOT NULL,
  title TEXT NOT NULL,
  kind TEXT NOT NULL CHECK(kind IN ('folder','audio','text','other')),
  size_bytes INTEGER NOT NULL CHECK(size_bytes >= 0), content_hash TEXT NOT NULL DEFAULT '', observed_generation INTEGER NOT NULL DEFAULT 0, modified_at TEXT NOT NULL DEFAULT '', parent_path TEXT GENERATED ALWAYS AS (
  CASE
    WHEN instr(relative_path, '/') = 0 THEN ''
    ELSE substr(relative_path, 1, length(rtrim(relative_path, replace(relative_path, '/', ''))) - 1)
  END
) VIRTUAL, source_root TEXT NOT NULL DEFAULT '',
  PRIMARY KEY(catalog_entry_id,relative_path)
);

CREATE TABLE source_catalog_observation (
    file_source_id INTEGER NOT NULL,
    directory_path TEXT NOT NULL,
    name TEXT NOT NULL,
    revision INTEGER NOT NULL,
    kind TEXT NOT NULL,
    size_bytes INTEGER NOT NULL,
    published_generation INTEGER NOT NULL DEFAULT 0, content_hash TEXT NOT NULL DEFAULT '', publish_pending INTEGER NOT NULL DEFAULT 0
    CHECK(publish_pending IN (0,1)), modified_at TEXT NOT NULL DEFAULT '',
    PRIMARY KEY(file_source_id,directory_path,name),
    FOREIGN KEY(file_source_id,directory_path) REFERENCES source_catalog_directory(file_source_id,path) ON DELETE CASCADE
);

CREATE TABLE source_catalog_phase_timing (
  workflow_run_id INTEGER NOT NULL REFERENCES workflow_run(id) ON DELETE CASCADE,
  phase TEXT NOT NULL CHECK(phase IN ('scan','publish','cleanup','lifecycle','settle')),
  started_at TEXT NOT NULL,
  finished_at TEXT NOT NULL,
  duration_ms INTEGER NOT NULL CHECK(duration_ms >= 0),
  included INTEGER NOT NULL DEFAULT 1 CHECK(included IN (0,1)),
  PRIMARY KEY(workflow_run_id, phase)
);

CREATE TABLE source_catalog_relocation_candidate (
    catalog_entry_id INTEGER NOT NULL REFERENCES source_catalog_entry(id) ON DELETE CASCADE,
    candidate_entry_id INTEGER NOT NULL REFERENCES source_catalog_entry(id) ON DELETE CASCADE,
    reason TEXT NOT NULL CHECK(reason IN ('insufficient_evidence','ambiguous_evidence','conflicting_identity')),
    generation INTEGER NOT NULL,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY(catalog_entry_id,candidate_entry_id),
    CHECK(catalog_entry_id<>candidate_entry_id)
);

CREATE TABLE source_catalog_scan (
    file_source_id INTEGER PRIMARY KEY REFERENCES file_source(id) ON DELETE CASCADE,
    workflow_run_id INTEGER NOT NULL REFERENCES workflow_run(id),
    options_json TEXT NOT NULL,
    pause_reason TEXT NOT NULL DEFAULT '',
    requests INTEGER NOT NULL DEFAULT 0,
    started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, lifecycle_stage TEXT NOT NULL DEFAULT 'observe'
    CHECK(lifecycle_stage IN ('observe','reconcile','done')), lifecycle_cursor INTEGER NOT NULL DEFAULT 0, publish_cleanup_cursor INTEGER NOT NULL DEFAULT 0, orphan_cleanup_cursor INTEGER NOT NULL DEFAULT 0, directories INTEGER NOT NULL DEFAULT 0, completed INTEGER NOT NULL DEFAULT 0, pending INTEGER NOT NULL DEFAULT 0, failed INTEGER NOT NULL DEFAULT 0, restricted INTEGER NOT NULL DEFAULT 0, empty INTEGER NOT NULL DEFAULT 0, observed INTEGER NOT NULL DEFAULT 0, indexed INTEGER NOT NULL DEFAULT 0, publish_cursor_path TEXT NOT NULL DEFAULT '', publish_cursor_name TEXT NOT NULL DEFAULT '', publish_pending_remaining INTEGER NOT NULL DEFAULT 0);

CREATE TABLE source_catalog_schedule (
  file_source_id INTEGER PRIMARY KEY REFERENCES file_source(id) ON DELETE CASCADE,
  daily_due_at INTEGER NOT NULL,
  weekly_due_at INTEGER NOT NULL,
  deferred_until INTEGER NOT NULL DEFAULT 0,
  deferred_reason TEXT NOT NULL DEFAULT '',
  manual_pending INTEGER NOT NULL DEFAULT 0 CHECK(manual_pending IN (0,1)),
  resume_full_pending INTEGER NOT NULL DEFAULT 0 CHECK(resume_full_pending IN (0,1)),
  pending_full_run_id INTEGER REFERENCES workflow_run(id) ON DELETE SET NULL,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE VIRTUAL TABLE source_catalog_search USING fts5(
  body,
  content='source_catalog_search_doc',
  content_rowid='id',
  tokenize='trigram'
);

CREATE TABLE source_catalog_search_doc (
  id INTEGER PRIMARY KEY,
  entity_kind TEXT NOT NULL CHECK(entity_kind IN ('entry','file','series')),
  entity_key TEXT NOT NULL,
  catalog_entry_id INTEGER NOT NULL DEFAULT 0,
  series_id INTEGER NOT NULL DEFAULT 0,
  file_source_id INTEGER NOT NULL DEFAULT 0,
  body TEXT NOT NULL,
  UNIQUE(entity_kind, entity_key)
);

CREATE TABLE source_catalog_sync_run (
  id INTEGER PRIMARY KEY,
  file_source_id INTEGER NOT NULL REFERENCES file_source(id) ON DELETE CASCADE,
  started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  finished_at TEXT,
  status TEXT NOT NULL DEFAULT 'running' CHECK(status IN ('running','succeeded','partial','failed','cancelled')),
  dirs_probed INTEGER NOT NULL DEFAULT 0,
  dirs_changed INTEGER NOT NULL DEFAULT 0,
  dirs_listed INTEGER NOT NULL DEFAULT 0,
  entries_published INTEGER NOT NULL DEFAULT 0,
  requests INTEGER NOT NULL DEFAULT 0,
  force INTEGER NOT NULL DEFAULT 0 CHECK(force IN (0,1)),
  note TEXT NOT NULL DEFAULT ''
);

CREATE TABLE "source_field_translation" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  cache_key TEXT NOT NULL UNIQUE,
  source_id INTEGER NOT NULL REFERENCES file_source(id) ON DELETE CASCADE,
  work_code TEXT NOT NULL DEFAULT '',
  field TEXT NOT NULL CHECK(field IN ('title','tag','directory')),
  path TEXT NOT NULL DEFAULT '',
  language TEXT NOT NULL,
  source_text TEXT NOT NULL,
  translated_text TEXT NOT NULL,
  model TEXT NOT NULL DEFAULT '',
  template_version TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE tag (
  id INTEGER PRIMARY KEY,
  namespace TEXT NOT NULL,
  normalized_name TEXT NOT NULL,
  display_name TEXT NOT NULL,
  language TEXT NOT NULL DEFAULT '',
  is_user_defined INTEGER NOT NULL DEFAULT 0 CHECK(is_user_defined IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(namespace, normalized_name, language)
);

CREATE TABLE translation_prefill_failure (
  entity_kind TEXT NOT NULL,
  entity_id INTEGER NOT NULL,
  field TEXT NOT NULL,
  language TEXT NOT NULL,
  config_key TEXT NOT NULL,
  source_hash TEXT NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0,
  -- NULL means the row is not scheduled. A failed attempt always sets a time;
  -- the column stays nullable so a future queue can park a row explicitly.
  next_retry_at TEXT,
  last_error TEXT NOT NULL DEFAULT '',
  PRIMARY KEY(entity_kind, entity_id, field, language, config_key, source_hash)
);

CREATE TABLE "translation_prefill_state" (
  id INTEGER PRIMARY KEY CHECK(id = 1),
  cursor_entry_id INTEGER NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'idle'
    CHECK(status IN ('idle','running','paused','complete','failed')),
  last_error TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  config_key TEXT NOT NULL DEFAULT '',
  cursor_language TEXT NOT NULL DEFAULT '',
  cursor_kind TEXT NOT NULL DEFAULT 'entry',
  cursor_field TEXT NOT NULL DEFAULT 'title',
  cursor_id INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE "user_account" (
  id INTEGER PRIMARY KEY,
  username TEXT NOT NULL UNIQUE,
  display_name TEXT NOT NULL DEFAULT '',
  role TEXT NOT NULL CHECK(role IN ('super_admin', 'admin', 'contributor', 'user')),
  enabled INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  ui_locale TEXT NOT NULL DEFAULT 'auto'
    CHECK(ui_locale IN ('auto', 'en', 'zh-Hans', 'zh-Hant', 'ja', 'ko'))
);

CREATE TABLE user_listening_day (
  user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  day TEXT NOT NULL,
  listened_seconds REAL NOT NULL DEFAULT 0 CHECK(listened_seconds >= 0),
  listen_count INTEGER NOT NULL DEFAULT 0 CHECK(listen_count >= 0),
  PRIMARY KEY(user_id, work_id, day)
);

CREATE TABLE user_listening_generation (
  user_id INTEGER PRIMARY KEY REFERENCES user_account(id) ON DELETE CASCADE,
  generation INTEGER NOT NULL DEFAULT 0 CHECK(generation >= 0)
);

CREATE TABLE user_listening_hour (
  user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
  day TEXT NOT NULL,
  hour INTEGER NOT NULL CHECK(hour BETWEEN 0 AND 23),
  listened_seconds REAL NOT NULL DEFAULT 0 CHECK(listened_seconds >= 0),
  PRIMARY KEY(user_id, day, hour)
);

CREATE TABLE user_listening_import (
  user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  listened_seconds REAL NOT NULL DEFAULT 0 CHECK(listened_seconds >= 0),
  listen_count INTEGER NOT NULL DEFAULT 0 CHECK(listen_count >= 0),
  last_played_at TEXT NOT NULL DEFAULT '',
  PRIMARY KEY(user_id, work_id)
);

CREATE TABLE user_listening_session (
  user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
  session_id TEXT NOT NULL,
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  listened_seconds REAL NOT NULL DEFAULT 0 CHECK(listened_seconds BETWEEN 0 AND 86400),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, dated_report INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY(user_id, session_id)
);

CREATE TABLE user_listening_session_day (
  user_id INTEGER NOT NULL,
  session_id TEXT NOT NULL,
  day TEXT NOT NULL,
  listened_seconds REAL NOT NULL CHECK(listened_seconds >= 0),
  PRIMARY KEY(user_id, session_id, day),
  FOREIGN KEY(user_id, session_id) REFERENCES user_listening_session(user_id, session_id) ON DELETE CASCADE
);

CREATE TABLE user_listening_session_hour (
  user_id INTEGER NOT NULL,
  session_id TEXT NOT NULL,
  day TEXT NOT NULL,
  hour INTEGER NOT NULL CHECK(hour BETWEEN 0 AND 23),
  listened_seconds REAL NOT NULL CHECK(listened_seconds >= 0),
  PRIMARY KEY(user_id, session_id, day, hour),
  FOREIGN KEY(user_id, session_id) REFERENCES user_listening_session(user_id, session_id) ON DELETE CASCADE
);

CREATE TABLE user_media_lyrics_preference (
  user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
  audio_media_item_id INTEGER NOT NULL REFERENCES media_item(id) ON DELETE CASCADE,
  lyrics_media_item_id INTEGER NOT NULL REFERENCES media_item(id) ON DELETE CASCADE,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(user_id, audio_media_item_id),
  CHECK(audio_media_item_id <> lyrics_media_item_id)
);

CREATE TABLE user_media_progress (
  user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
  media_item_id INTEGER NOT NULL REFERENCES media_item(id) ON DELETE CASCADE,
  position_seconds REAL NOT NULL DEFAULT 0,
  duration_seconds REAL,
  completed INTEGER NOT NULL DEFAULT 0,
  last_played_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(user_id, media_item_id)
);

CREATE TABLE user_party_state (
  user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
  party_id INTEGER NOT NULL REFERENCES party(id) ON DELETE CASCADE,
  rating INTEGER,
  note TEXT NOT NULL DEFAULT '',
  favorite INTEGER NOT NULL DEFAULT 0,
  last_viewed_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(user_id, party_id)
);

CREATE TABLE user_party_tag (
  id INTEGER PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  color TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(user_id, name)
);

CREATE TABLE user_party_tag_assignment (
  user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
  party_id INTEGER NOT NULL REFERENCES party(id) ON DELETE CASCADE,
  user_party_tag_id INTEGER NOT NULL REFERENCES user_party_tag(id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(user_id, party_id, user_party_tag_id)
);

CREATE TABLE user_password_credential (
  user_id INTEGER PRIMARY KEY REFERENCES user_account(id) ON DELETE CASCADE,
  password_hash TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE user_person_state (
  user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
  person_id INTEGER NOT NULL REFERENCES person(id) ON DELETE CASCADE,
  rating INTEGER,
  note TEXT NOT NULL DEFAULT '',
  favorite INTEGER NOT NULL DEFAULT 0,
  last_viewed_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(user_id, person_id)
);

CREATE TABLE user_person_tag (
  id INTEGER PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  color TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(user_id, name)
);

CREATE TABLE user_person_tag_assignment (
  user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
  person_id INTEGER NOT NULL REFERENCES person(id) ON DELETE CASCADE,
  user_person_tag_id INTEGER NOT NULL REFERENCES user_person_tag(id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(user_id, person_id, user_person_tag_id)
);

CREATE TABLE user_preference (
  user_id INTEGER PRIMARY KEY REFERENCES user_account(id) ON DELETE CASCADE,
  directory_routing_rules TEXT,
  recommendation_config TEXT,
  recommendation_threshold INTEGER CHECK (recommendation_threshold BETWEEN 1 AND 100)
, metadata_languages TEXT, time_zone TEXT);

CREATE TABLE user_session (
  id TEXT PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
  expires_at TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE user_tag (
  id INTEGER PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  color TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(user_id, name)
);

CREATE TABLE user_work_playback_cursor (
  user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  media_item_id INTEGER NOT NULL REFERENCES media_item(id) ON DELETE CASCADE,
  file_source_id INTEGER REFERENCES file_source(id) ON DELETE SET NULL,
  location_id INTEGER REFERENCES media_file_location(id) ON DELETE SET NULL,
  location_type TEXT NOT NULL DEFAULT '',
  position_seconds REAL NOT NULL DEFAULT 0,
  duration_seconds REAL,
  completed INTEGER NOT NULL DEFAULT 0,
  last_played_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, report_order INTEGER NOT NULL DEFAULT 0, report_id TEXT NOT NULL DEFAULT '',
  PRIMARY KEY(user_id, work_id)
);

CREATE TABLE user_work_state (
  user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  listening_status TEXT NOT NULL DEFAULT 'none' CHECK(listening_status IN ('none', 'want_to_listen', 'listening', 'finished', 'relisten', 'paused')),
  favorite INTEGER NOT NULL DEFAULT 0,
  rating INTEGER,
  note TEXT NOT NULL DEFAULT '',
  last_played_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(user_id, work_id)
);

CREATE TABLE user_work_tag (
  user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  user_tag_id INTEGER NOT NULL REFERENCES user_tag(id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(user_id, work_id, user_tag_id)
);

CREATE TABLE voice_catalog_item (
  id INTEGER PRIMARY KEY,
  person_id INTEGER NOT NULL REFERENCES person(id) ON DELETE CASCADE,
  primary_code TEXT NOT NULL,
  work_id INTEGER REFERENCES work(id) ON DELETE SET NULL,
  title TEXT NOT NULL DEFAULT '',
  release_date TEXT,
  cover_url TEXT NOT NULL DEFAULT '',
  source_url TEXT NOT NULL DEFAULT '',
  circle TEXT NOT NULL DEFAULT '',
  age_rating TEXT NOT NULL DEFAULT '',
  rating_average REAL,
  rating_count INTEGER,
  sales_count INTEGER,
  current_price INTEGER,
  tags_json TEXT NOT NULL DEFAULT '[]',
  voice_actors_json TEXT NOT NULL DEFAULT '[]',
  raw_json TEXT NOT NULL DEFAULT '{}',
  catalog_status TEXT NOT NULL DEFAULT 'catalog',
  snapshot_generation INTEGER NOT NULL DEFAULT 0,
  last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(person_id, primary_code)
);

CREATE TABLE voice_catalog_refresh_state (
  person_id INTEGER PRIMARY KEY REFERENCES person(id) ON DELETE CASCADE,
  generation INTEGER NOT NULL DEFAULT 0,
  query_json TEXT NOT NULL DEFAULT '[]',
  source_status_json TEXT NOT NULL DEFAULT '[]',
  last_success_at TEXT,
  last_attempt_at TEXT,
  last_status TEXT NOT NULL DEFAULT '',
  last_run_id INTEGER REFERENCES workflow_run(id) ON DELETE SET NULL,
  last_error TEXT NOT NULL DEFAULT '',
  complete INTEGER NOT NULL DEFAULT 0,
  pages_fetched INTEGER NOT NULL DEFAULT 0,
  catalog_works INTEGER NOT NULL DEFAULT 0,
  metadata_queued INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE voice_catalog_source (
  id INTEGER PRIMARY KEY,
  catalog_item_id INTEGER NOT NULL REFERENCES voice_catalog_item(id) ON DELETE CASCADE,
  provider_id INTEGER NOT NULL REFERENCES metadata_provider(id),
  remote_id TEXT NOT NULL DEFAULT '',
  remote_code TEXT NOT NULL,
  source_url TEXT NOT NULL DEFAULT '',
  availability TEXT NOT NULL DEFAULT 'unknown',
  raw_json TEXT NOT NULL DEFAULT '{}',
  snapshot_generation INTEGER NOT NULL DEFAULT 0,
  last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_checked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(catalog_item_id, provider_id, remote_code)
);

CREATE TABLE "work" (
  id INTEGER PRIMARY KEY,
  primary_code TEXT NOT NULL DEFAULT '',
  work_type TEXT NOT NULL DEFAULT 'audio',
  title TEXT NOT NULL,
  title_kana TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  release_date TEXT,
  age_rating TEXT NOT NULL DEFAULT '',
  cover_asset_id INTEGER,
  duration_seconds INTEGER,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, rating_average REAL, sales_count INTEGER CHECK(sales_count IS NULL OR sales_count >= 0), regular_price INTEGER CHECK(regular_price IS NULL OR regular_price >= 0), current_price INTEGER CHECK(current_price IS NULL OR current_price >= 0), price_currency TEXT NOT NULL DEFAULT '', is_permanently_free INTEGER CHECK(is_permanently_free IS NULL OR is_permanently_free IN (0, 1)), recommendation_explore_key INTEGER NOT NULL DEFAULT 0, parent_work_id INTEGER REFERENCES work(id) ON DELETE RESTRICT);

CREATE TABLE work_code_alias (
  id INTEGER PRIMARY KEY,
  logical_work_id INTEGER NOT NULL REFERENCES logical_work(id) ON DELETE CASCADE,
  provider_id INTEGER NOT NULL REFERENCES metadata_provider(id),
  primary_code TEXT NOT NULL,
  metadata_language TEXT NOT NULL DEFAULT '',
  edition_label TEXT NOT NULL DEFAULT '',
  source_work_id INTEGER REFERENCES work(id) ON DELETE SET NULL,
  relationship_kind TEXT NOT NULL DEFAULT 'provider_declared',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(provider_id, primary_code)
);

CREATE TABLE work_credit (
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  person_id INTEGER NOT NULL REFERENCES person(id) ON DELETE CASCADE,
  role TEXT NOT NULL,
  provider_id INTEGER REFERENCES metadata_provider(id),
  source TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(work_id, person_id, role)
);

CREATE TABLE work_dlsite_genre (
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  genre_id INTEGER NOT NULL CHECK(genre_id > 0),
  PRIMARY KEY (work_id, genre_id)
);

CREATE TABLE work_edition (
  work_id INTEGER PRIMARY KEY REFERENCES work(id) ON DELETE CASCADE,
  logical_work_id INTEGER NOT NULL REFERENCES logical_work(id) ON DELETE CASCADE,
  provider_id INTEGER REFERENCES metadata_provider(id),
  primary_code TEXT NOT NULL,
  base_code TEXT NOT NULL DEFAULT '',
  metadata_language TEXT NOT NULL DEFAULT '',
  edition_label TEXT NOT NULL DEFAULT '',
  is_canonical INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, translation_kind TEXT NOT NULL DEFAULT 'unknown', classification_source TEXT NOT NULL DEFAULT '', maker_id TEXT NOT NULL DEFAULT '', origin_maker_id TEXT NOT NULL DEFAULT '');

CREATE TABLE work_external_id (
  id INTEGER PRIMARY KEY,
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  provider_id INTEGER NOT NULL REFERENCES metadata_provider(id),
  id_type TEXT NOT NULL,
  external_id TEXT NOT NULL,
  url TEXT NOT NULL DEFAULT '',
  is_primary INTEGER NOT NULL DEFAULT 0,
  UNIQUE(provider_id, id_type, external_id)
);

CREATE TABLE work_folder_location (
  id INTEGER PRIMARY KEY,
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  file_source_id INTEGER NOT NULL REFERENCES file_source(id) ON DELETE CASCADE,
  root_path TEXT NOT NULL,
  role TEXT NOT NULL DEFAULT 'external',
  origin_source_id INTEGER REFERENCES file_source(id) ON DELETE SET NULL,
  origin_remote_code TEXT NOT NULL DEFAULT '',
  state TEXT NOT NULL DEFAULT 'active',
  is_primary INTEGER NOT NULL DEFAULT 0,
  last_scanned_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, cleanup_run_id INTEGER REFERENCES workflow_run(id) ON DELETE SET NULL,
  UNIQUE(file_source_id, root_path)
);

CREATE TABLE "work_manual_override" (
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  field_name TEXT NOT NULL,
  language TEXT NOT NULL DEFAULT '' CHECK (language IN ('', 'ja-jp', 'zh-cn', 'zh-tw', 'en-us', 'ko-kr')),
  value_json TEXT NOT NULL DEFAULT 'null',
  asset_path TEXT NOT NULL DEFAULT '',
  updated_by_user_id INTEGER REFERENCES user_account(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(work_id, field_name, language),
  CHECK (field_name = 'title' OR language = '')
);

CREATE TABLE work_matching_control (
 id INTEGER PRIMARY KEY CHECK(id=1),
 revision INTEGER NOT NULL DEFAULT 1,
 scan_revision INTEGER NOT NULL DEFAULT 0,
 cursor_kind TEXT NOT NULL DEFAULT '',
 cursor_id INTEGER NOT NULL DEFAULT 0,
 status TEXT NOT NULL DEFAULT 'queued',
 attempts INTEGER NOT NULL DEFAULT 0,
 retry_after INTEGER NOT NULL DEFAULT 0,
 last_request INTEGER NOT NULL DEFAULT 0,
 error_code TEXT NOT NULL DEFAULT ''
);

CREATE TABLE work_matching_operation (
 operation_id INTEGER PRIMARY KEY REFERENCES shared_association(id) ON DELETE CASCADE,
 subject_kind TEXT NOT NULL,
 subject_id INTEGER NOT NULL,
 evidence_fingerprint TEXT NOT NULL,
 rule TEXT NOT NULL
);

CREATE TABLE work_matching_result (
 kind TEXT NOT NULL CHECK(kind IN ('work','catalog','series')),
 entity_id INTEGER NOT NULL,
 result_json TEXT NOT NULL,
 updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, revision INTEGER NOT NULL DEFAULT 0,
 PRIMARY KEY(kind,entity_id)
);

CREATE TABLE work_metadata_field_source (
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  field_name TEXT NOT NULL CHECK(field_name IN ('title', 'release_date', 'age_rating', 'duration', 'circle', 'tags', 'cover')),
  provider_id INTEGER NOT NULL REFERENCES metadata_provider(id) ON DELETE CASCADE,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(work_id, field_name)
) WITHOUT ROWID;

CREATE TABLE work_metadata_link (
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  provider_id INTEGER NOT NULL REFERENCES metadata_provider(id) ON DELETE CASCADE,
  source_code TEXT NOT NULL CHECK(source_code <> ''),
  updated_by_user_id INTEGER REFERENCES user_account(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(work_id, provider_id)
);

CREATE TABLE work_metadata_provider_state (
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  provider_id INTEGER NOT NULL REFERENCES metadata_provider(id) ON DELETE CASCADE,
  status TEXT NOT NULL CHECK(status IN ('available', 'not_found')),
  message TEXT NOT NULL DEFAULT '',
  checked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(work_id, provider_id)
);

CREATE TABLE work_metadata_sync_state (
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  provider_id INTEGER NOT NULL REFERENCES metadata_provider(id) ON DELETE CASCADE,
  component TEXT NOT NULL CHECK(component IN ('metadata', 'cover')),
  attempt_id INTEGER NOT NULL REFERENCES metadata_sync_attempt(id),
  last_success_attempt_id INTEGER NOT NULL DEFAULT 0,
  status TEXT NOT NULL CHECK(status IN ('succeeded', 'failed', 'unavailable')),
  failure_count INTEGER NOT NULL DEFAULT 0,
  first_failed_at TEXT,
  checked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(work_id, provider_id, component)
);

CREATE TABLE work_metadata_tag_base (
 work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
 tag_id INTEGER NOT NULL REFERENCES metadata_tag(tag_id) ON DELETE RESTRICT,
 PRIMARY KEY(work_id,tag_id)
);

CREATE TABLE work_metadata_tag_dirty (
 work_id INTEGER PRIMARY KEY REFERENCES work(id) ON DELETE CASCADE,
 retry_count INTEGER NOT NULL DEFAULT 0,
 retry_after INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE work_metadata_tag_projection (
 work_id INTEGER PRIMARY KEY REFERENCES work(id) ON DELETE CASCADE,
 source_work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE
);

CREATE TABLE work_parent_backfill_report (
  work_id INTEGER PRIMARY KEY REFERENCES work(id) ON DELETE CASCADE,
  reason TEXT NOT NULL CHECK(reason IN ('missing','conflict','multi_parent')),
  detail TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE work_party (
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  party_id INTEGER NOT NULL REFERENCES party(id) ON DELETE CASCADE,
  role TEXT NOT NULL DEFAULT 'circle',
  provider_id INTEGER REFERENCES metadata_provider(id),
  source TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(work_id, party_id, role)
);

CREATE TABLE work_purchase_bonus (
  work_id INTEGER PRIMARY KEY REFERENCES work(id) ON DELETE CASCADE,
  provider_id INTEGER NOT NULL REFERENCES metadata_provider(id) ON DELETE CASCADE,
  parent_code TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL CHECK(status IN ('linked', 'unmatched', 'dismissed')),
  origin TEXT NOT NULL CHECK(origin IN ('detected', 'user')),
  evidence TEXT NOT NULL DEFAULT '',
  updated_by_user_id INTEGER REFERENCES user_account(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK((status = 'linked') = (parent_code <> ''))
);

CREATE VIRTUAL TABLE work_search USING fts5(
  code,
  title,
  circle,
  voice_actor,
  tag,
  tokenize = 'trigram'
);

CREATE TABLE work_search_dirty (
  work_id INTEGER PRIMARY KEY
);

CREATE TABLE work_snapshot_projection (
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK(kind IN ('voice_credit', 'dlsite_party')),
  snapshot_id INTEGER NOT NULL,
  version INTEGER NOT NULL,
  input_hash TEXT NOT NULL,
  PRIMARY KEY(work_id, kind)
) WITHOUT ROWID;

CREATE TABLE work_source_presence (
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  file_source_id INTEGER NOT NULL REFERENCES file_source(id) ON DELETE CASCADE,
  presence_type TEXT NOT NULL DEFAULT 'location',
  remote_id TEXT NOT NULL DEFAULT '',
  remote_code TEXT NOT NULL DEFAULT '',
  source_url TEXT NOT NULL DEFAULT '',
  availability TEXT NOT NULL DEFAULT 'unknown',
  raw_json TEXT NOT NULL DEFAULT '{}',
  last_seen_at TEXT,
  last_checked_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(work_id, file_source_id, presence_type)
);

CREATE TABLE work_tag (
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  tag_id INTEGER NOT NULL REFERENCES tag(id) ON DELETE CASCADE,
  source TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(work_id, tag_id, source)
);

CREATE TABLE work_tag_override (
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  tag_id INTEGER NOT NULL REFERENCES metadata_tag(tag_id) ON DELETE RESTRICT,
  action TEXT NOT NULL CHECK(action IN ('add', 'remove')),
  updated_by_user_id INTEGER REFERENCES user_account(id) ON DELETE SET NULL,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(work_id, tag_id)
);

CREATE TABLE work_title_language (
  work_id INTEGER NOT NULL REFERENCES work(id) ON DELETE CASCADE,
  language TEXT NOT NULL CHECK(language IN ('origin', 'ja-jp', 'zh-cn', 'zh-tw', 'en-us', 'ko-kr')),
  title TEXT NOT NULL,
  PRIMARY KEY(work_id, language)
) WITHOUT ROWID;

CREATE TABLE work_title_language_dirty (
  work_id INTEGER PRIMARY KEY
);

CREATE TABLE workflow_candidate (
  id INTEGER PRIMARY KEY,
  workflow_run_id INTEGER NOT NULL REFERENCES workflow_run(id) ON DELETE CASCADE,
  workflow_node_run_id INTEGER REFERENCES workflow_node_run(id) ON DELETE SET NULL,
  candidate_type TEXT NOT NULL,
  external_key TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL,
  payload_json TEXT NOT NULL DEFAULT '{}',
  decision_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE workflow_definition (
  id INTEGER PRIMARY KEY,
  code TEXT NOT NULL UNIQUE,
  display_name TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  definition_json TEXT NOT NULL DEFAULT '{}',
  scope TEXT NOT NULL DEFAULT 'system' CHECK(scope IN ('system', 'user')),
  editable INTEGER NOT NULL DEFAULT 0 CHECK(editable IN (0, 1)),
  owner_user_id INTEGER REFERENCES user_account(id) ON DELETE SET NULL,
  created_by_user_id INTEGER REFERENCES user_account(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE workflow_event (
  id INTEGER PRIMARY KEY,
  workflow_run_id INTEGER NOT NULL REFERENCES workflow_run(id) ON DELETE CASCADE,
  workflow_node_run_id INTEGER REFERENCES workflow_node_run(id) ON DELETE SET NULL,
  workflow_job_id INTEGER REFERENCES workflow_job(id) ON DELETE SET NULL,
  level TEXT NOT NULL DEFAULT 'info',
  event_type TEXT NOT NULL,
  message TEXT NOT NULL,
  detail_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE workflow_job (
  id INTEGER PRIMARY KEY,
  workflow_run_id INTEGER NOT NULL REFERENCES workflow_run(id) ON DELETE CASCADE,
  workflow_node_run_id INTEGER REFERENCES workflow_node_run(id) ON DELETE SET NULL,
  worker_type TEXT NOT NULL,
  status TEXT NOT NULL,
  payload_json TEXT NOT NULL DEFAULT '{}',
  retry_count INTEGER NOT NULL DEFAULT 0,
  error_message TEXT NOT NULL DEFAULT '',
  progress_current INTEGER NOT NULL DEFAULT 0,
  progress_total INTEGER NOT NULL DEFAULT 0,
  locked_by TEXT NOT NULL DEFAULT '',
  locked_at TEXT,
  heartbeat_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, checkpoint_json TEXT NOT NULL DEFAULT '{}', recoverable INTEGER NOT NULL DEFAULT 0, max_retries INTEGER NOT NULL DEFAULT 3, resume_count INTEGER NOT NULL DEFAULT 0, available_at TEXT, priority INTEGER NOT NULL DEFAULT 0, resource_key TEXT NOT NULL DEFAULT '', progress_bytes_current INTEGER NOT NULL DEFAULT 0 CHECK(progress_bytes_current >= 0), progress_bytes_total INTEGER NOT NULL DEFAULT 0 CHECK(progress_bytes_total >= 0), progress_bytes_unknown_items INTEGER NOT NULL DEFAULT 0 CHECK(progress_bytes_unknown_items >= 0));

CREATE TABLE workflow_node_run (
  id INTEGER PRIMARY KEY,
  workflow_run_id INTEGER NOT NULL REFERENCES workflow_run(id) ON DELETE CASCADE,
  node_id TEXT NOT NULL,
  node_type TEXT NOT NULL,
  display_name TEXT NOT NULL,
  position INTEGER NOT NULL DEFAULT 0,
  status TEXT NOT NULL,
  input_json TEXT NOT NULL DEFAULT '{}',
  output_json TEXT NOT NULL DEFAULT '{}',
  error_message TEXT NOT NULL DEFAULT '',
  started_at TEXT,
  finished_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE workflow_notification (
  id INTEGER PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
  workflow_run_id INTEGER NOT NULL REFERENCES workflow_run(id) ON DELETE CASCADE,
  notification_type TEXT NOT NULL,
  status TEXT NOT NULL,
  work_id INTEGER REFERENCES work(id) ON DELETE SET NULL,
  work_code TEXT NOT NULL DEFAULT '',
  message TEXT NOT NULL DEFAULT '',
  dismissed_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(user_id, workflow_run_id, notification_type)
);

CREATE TABLE workflow_run (
  id INTEGER PRIMARY KEY,
  workflow_definition_id INTEGER REFERENCES workflow_definition(id) ON DELETE SET NULL,
  trigger_id INTEGER REFERENCES workflow_trigger(id) ON DELETE SET NULL,
  workflow_code TEXT NOT NULL,
  display_name TEXT NOT NULL,
  status TEXT NOT NULL,
  trigger_type TEXT NOT NULL,
  trigger_reason TEXT NOT NULL DEFAULT '',
  input_json TEXT NOT NULL DEFAULT '{}',
  summary_json TEXT NOT NULL DEFAULT '{}',
  started_at TEXT,
  finished_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE workflow_run_review (
  id INTEGER PRIMARY KEY,
  workflow_run_id INTEGER NOT NULL REFERENCES workflow_run(id) ON DELETE CASCADE,
  user_id INTEGER NOT NULL REFERENCES user_account(id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'reviewed',
  note TEXT NOT NULL DEFAULT '',
  reviewed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(workflow_run_id, user_id)
);

CREATE TABLE workflow_trigger (
  id INTEGER PRIMARY KEY,
  workflow_definition_id INTEGER NOT NULL REFERENCES workflow_definition(id) ON DELETE CASCADE,
  trigger_type TEXT NOT NULL,
  display_name TEXT NOT NULL,
  enabled INTEGER NOT NULL DEFAULT 1,
  schedule_json TEXT NOT NULL DEFAULT '{}',
  config_json TEXT NOT NULL DEFAULT '{}',
  next_run_at TEXT,
  last_run_at TEXT,
  last_success_at TEXT,
  last_error_message TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

