INSERT INTO "workflow_definition" ("id", "code", "display_name", "description", "definition_json", "scope", "editable", "owner_user_id", "created_by_user_id") VALUES (2, 'local_library_scan', 'Scan local library', 'Discover local works and synchronize local source presence.', '{"nodes":[{"id":"select","type":"select_local_source","displayName":"Select local source"},{"id":"discover","type":"discover_local_files","displayName":"Discover files"},{"id":"match","type":"match_works","displayName":"Match works"},{"id":"sync","type":"sync_file_locations","displayName":"Sync locations"}]}', 'system', 0, NULL, NULL);
INSERT INTO "workflow_definition" ("id", "code", "display_name", "description", "definition_json", "scope", "editable", "owner_user_id", "created_by_user_id") VALUES (3, 'metadata_sync', 'Sync work metadata', 'Select works and sync normalized metadata snapshots.', '{"nodes":[{"id":"select","type":"select_works"},{"id":"sync","type":"sync_metadata"}]}', 'system', 0, NULL, NULL);
INSERT INTO "workflow_definition" ("id", "code", "display_name", "description", "definition_json", "scope", "editable", "owner_user_id", "created_by_user_id") VALUES (4, 'remote_source_sync', 'Sync remote source', 'Discover remote works, filter candidates, match works, and sync remote locations.', '{"nodes":[{"id":"select","type":"select_remote_source"},{"id":"discover","type":"discover_remote_works"},{"id":"filter","type":"filter_candidates"},{"id":"match","type":"match_works"},{"id":"sync","type":"sync_file_locations"}]}', 'system', 0, NULL, NULL);
INSERT INTO "workflow_definition" ("id", "code", "display_name", "description", "definition_json", "scope", "editable", "owner_user_id", "created_by_user_id") VALUES (5, 'media_cache', 'Cache media', 'Select media items, filter cache misses, sync source state, and materialize cache files.', '{"nodes":[{"id":"select","type":"select_media_items"},{"id":"filter","type":"filter_candidates"},{"id":"sync","type":"sync_file_locations"},{"id":"cache","type":"materialize_cache"}]}', 'system', 0, NULL, NULL);
INSERT INTO "workflow_definition" ("id", "code", "display_name", "description", "definition_json", "scope", "editable", "owner_user_id", "created_by_user_id") VALUES (6, 'media_save', 'Save media to local library', 'Select media items or folders, sync source state, cache when needed, and save to a local source.', '{"nodes":[{"id":"select","type":"select_media_items"},{"id":"filter","type":"filter_candidates"},{"id":"sync","type":"sync_file_locations"},{"id":"cache","type":"materialize_cache"},{"id":"save","type":"materialize_save"}]}', 'system', 0, NULL, NULL);
