CREATE VIEW catalog_entry_searchable AS
SELECT e.id AS catalog_entry_id, e.title AS title,
  CASE WHEN e.relocated_to_id IS NULL AND e.file_source_id IS NOT NULL
    AND trim(e.title)<>''
    AND EXISTS(SELECT 1 FROM file_source src
               WHERE src.id=e.file_source_id
                 AND src.enabled=1 AND src.source_type='openlist')
    AND NOT EXISTS(
      SELECT 1 FROM source_catalog_episode_pending pending
      WHERE pending.catalog_entry_id=e.id
        AND NOT EXISTS(
          SELECT 1 FROM source_catalog_episode_publication publication
          WHERE publication.source_id=pending.source_id
            AND publication.parent_root=pending.parent_root
            AND publication.state='published'))
    AND COALESCE(
      (SELECT adm.audio>0 AND adm.files<=5000
              AND NOT (adm.non_audio>2000 AND adm.audio<5)
       FROM source_catalog_entry_admission adm
       WHERE adm.catalog_entry_id=e.id AND adm.generation=e.last_seen_generation),
      (SELECT live.audio>0 AND live.files<=5000
              AND NOT (live.non_audio>2000 AND live.audio<5)
       FROM (SELECT
         (SELECT count(*) FROM (SELECT 1 FROM source_catalog_file af
           WHERE af.catalog_entry_id=e.id AND af.kind<>'folder'
             AND af.observed_generation=e.last_seen_generation LIMIT 5001)) AS files,
         (SELECT count(*) FROM (SELECT 1 FROM source_catalog_file aaf
           WHERE aaf.catalog_entry_id=e.id AND aaf.kind='audio'
             AND aaf.observed_generation=e.last_seen_generation LIMIT 5)) AS audio,
         (SELECT count(*) FROM (SELECT 1 FROM source_catalog_file anf
           WHERE anf.catalog_entry_id=e.id AND anf.kind<>'audio' AND anf.kind<>'folder'
             AND anf.observed_generation=e.last_seen_generation LIMIT 2001)) AS non_audio) AS live))
  THEN 1 ELSE 0 END AS searchable
FROM source_catalog_entry e;

CREATE VIEW content_translation_scope AS
SELECT ct.id AS translation_id,
  CASE ct.entity_kind
    WHEN 'entry' THEN (SELECT e.file_source_id FROM source_catalog_entry e WHERE e.id=ct.entity_id)
    WHEN 'series' THEN (SELECT s.source_id FROM catalog_series s WHERE s.id=ct.entity_id)
    ELSE NULL END AS source_id,
  CASE ct.entity_kind
    WHEN 'entry' THEN (CASE WHEN ct.field='title' AND EXISTS(
      SELECT 1 FROM catalog_entry_searchable entry_scope
      WHERE entry_scope.catalog_entry_id=ct.entity_id
        AND entry_scope.searchable=1 AND entry_scope.title=ct.source_text)
      THEN 1 ELSE 0 END)
    WHEN 'series' THEN (CASE WHEN ct.field='title' AND EXISTS(
      SELECT 1 FROM catalog_series s
      JOIN file_source src ON src.id=s.source_id
      WHERE s.id=ct.entity_id AND s.source_id IS NOT NULL
        AND src.enabled=1 AND src.source_type='openlist'
        AND trim(s.title)<>'' AND s.title=ct.source_text
        AND (SELECT COUNT(*) FROM catalog_series_member m WHERE m.series_id=s.id)>=2
        AND EXISTS(
          SELECT 1 FROM catalog_series_member m
          JOIN catalog_entry_searchable member_scope ON member_scope.catalog_entry_id=m.catalog_entry_id
          WHERE m.series_id=s.id AND member_scope.searchable=1))
      THEN 1 ELSE 0 END)
    ELSE (CASE WHEN EXISTS(
      SELECT 1 FROM work w
      WHERE w.id=ct.entity_id
        AND NOT EXISTS(SELECT 1 FROM catalog_series s WHERE s.work_id=w.id)
        AND ((ct.field='title' AND trim(w.title)<>'' AND w.title=ct.source_text)
          OR (ct.field='description' AND trim(w.description)<>'' AND w.description=ct.source_text)))
      THEN 1 ELSE 0 END)
  END AS browsable
FROM content_translation ct;

CREATE VIEW metadata_tag_resolution AS
 WITH RECURSIVE resolution(source_tag_id,tag_id,next_tag_id) AS (
 SELECT tag_id,tag_id,merged_into_tag_id FROM metadata_tag
 UNION
 SELECT resolution.source_tag_id,concept.tag_id,concept.merged_into_tag_id FROM resolution
 JOIN metadata_tag AS concept ON concept.tag_id=resolution.next_tag_id
 ) SELECT source_tag_id,tag_id AS resolved_tag_id FROM resolution WHERE next_tag_id IS NULL;

CREATE VIEW shared_work_identity AS
 SELECT w.id AS work_id,COALESCE(m.identity_work_id,w.id) AS identity_work_id
 FROM work w LEFT JOIN shared_identity_member m ON m.work_id=w.id;

CREATE VIEW work_matching_subject AS
 SELECT 'work' AS kind,id,title,primary_code,id AS work_id FROM work
 UNION ALL SELECT 'catalog',id,title,primary_code,NULL FROM source_catalog_entry
   WHERE work_id IS NULL AND relocated_to_id IS NULL AND file_source_id IS NOT NULL
 UNION ALL SELECT 'series',id,title,'',NULL FROM catalog_series WHERE work_id IS NULL;

CREATE VIEW work_primary_circle AS
WITH family_target AS (
  SELECT
    work.id AS work_id,
    COALESCE(logical.canonical_work_id, work.id) AS canonical_work_id
  FROM work
  LEFT JOIN work_edition AS edition ON edition.work_id = work.id
  LEFT JOIN logical_work AS logical ON logical.id = edition.logical_work_id
), ranked AS (
  SELECT
    target.work_id,
    relation.party_id,
    party.display_name,
    COALESCE(external.external_id, '') AS external_id,
    relation.role,
    relation.source,
    ROW_NUMBER() OVER (
      PARTITION BY target.work_id
      ORDER BY
        CASE
          WHEN relation.work_id = target.work_id AND relation.source = 'manual_override' THEN 0
          WHEN relation.work_id = target.canonical_work_id AND relation.source = 'manual_override' THEN 1
          WHEN relation.work_id = target.canonical_work_id
            AND edition.maker_id <> ''
            AND UPPER(COALESCE(external.external_id, '')) = UPPER(edition.maker_id) THEN 2
          WHEN relation.work_id = target.canonical_work_id
            AND relation_provider.code = 'dlsite'
            AND relation.source IN ('dlsite_snapshot', 'dlsite_product', 'dlsite_edition') THEN 3
          WHEN relation.work_id = target.canonical_work_id
            AND relation_provider.code = 'dlsite' THEN 4
          WHEN edition.maker_id <> ''
            AND UPPER(COALESCE(external.external_id, '')) = UPPER(edition.maker_id) THEN 5
          WHEN relation_provider.code = 'dlsite'
            AND relation.source IN ('dlsite_snapshot', 'dlsite_product', 'dlsite_edition') THEN 6
          WHEN relation_provider.code = 'dlsite' THEN 7
          WHEN relation.source = 'remote_source' THEN 9
          ELSE 8
        END,
        relation.party_id ASC
    ) AS position
  FROM family_target AS target
  INNER JOIN work_party AS relation
    ON relation.work_id = target.work_id
    OR relation.work_id = target.canonical_work_id
  INNER JOIN party ON party.id = relation.party_id
  LEFT JOIN work_edition AS edition ON edition.work_id = relation.work_id
  LEFT JOIN metadata_provider AS relation_provider ON relation_provider.id = relation.provider_id
  LEFT JOIN party_external_id AS external ON external.id = (
    SELECT candidate.id
    FROM party_external_id AS candidate
    LEFT JOIN metadata_provider AS candidate_provider ON candidate_provider.id = candidate.provider_id
    WHERE candidate.party_id = party.id
    ORDER BY
      CASE WHEN candidate_provider.code = 'dlsite' THEN 0 ELSE 1 END,
      candidate.is_primary DESC,
      candidate.id ASC
    LIMIT 1
  )
  WHERE relation.role = 'circle'
)
SELECT work_id, party_id, display_name, external_id, role, source
FROM ranked
WHERE position = 1;

CREATE TRIGGER content_translation_ad AFTER DELETE ON content_translation BEGIN
  INSERT INTO content_translation_search(content_translation_search, rowid, translated_text)
  VALUES ('delete', old.id, old.translated_text);
END;

CREATE TRIGGER content_translation_ai AFTER INSERT ON content_translation BEGIN
  INSERT INTO content_translation_search(rowid, translated_text)
  VALUES (new.id, new.translated_text);
END;

CREATE TRIGGER content_translation_au AFTER UPDATE OF translated_text ON content_translation BEGIN
  INSERT INTO content_translation_search(content_translation_search, rowid, translated_text)
  VALUES ('delete', old.id, old.translated_text);
  INSERT INTO content_translation_search(rowid, translated_text)
  VALUES (new.id, new.translated_text);
END;

